# -*- coding: utf-8 -*-
"""
BlokQR - Module 2a (n4) : entitlement Pro signe + route /v1/analyze/deep.

- CREE app/security/entitlement.py : jeton Pro signe (Ed25519 + ML-DSA),
  emis par /v1/billing/verify (Module 3), verifie cote serveur ET cote client
  (cles du manifeste). Modele bearer, sans identite (privacy-first).
- AJOUTE le champ `entitlement` a AnalyzeRequest (app/schemas.py).
- AJOUTE la route POST /v1/analyze/deep (Pro, deep=True -> sandbox Chromium),
  402 si l'entitlement est absent/invalide (app/api/routes.py).

A executer DEPUIS /opt/blokqr/backend :
    cd /opt/blokqr/backend
    python3 patch_m2a_deep_route.py

Idempotent. Contenus base64. Abandon si une ancre est absente. Controle syntaxe.
"""
import ast, base64, io, os, sys
dec=lambda s: base64.b64decode(s).decode("utf-8")

ENT_B64=''
SCH=('', '', 'entitlement: Optional[str] = Field(')
RT=[('ZnJvbSBmYXN0YXBpIGltcG9ydCBBUElSb3V0ZXIsIERlcGVuZHMsIFJlcXVlc3QKCmZyb20gYXBwLmNvbmZpZyBpbXBvcnQgU2V0dGluZ3MsIGdldF9zZXR0aW5ncwpmcm9tIGFwcC5waXBlbGluZSBpbXBvcnQgYW5hbHl6ZSwgYnVpbGRfdGltZW91dF92ZXJkaWN0CmZyb20gYXBwLmFuYWx5emVycy5yZXB1dGF0aW9uX2thbm9uIGltcG9ydCBnZXRfc3RvcmU=', '', 'from app.security.entitlement import verify_entitlement'), ('', '', '/v1/analyze/deep')]

def write_new(path, content_b64, marker):
    if os.path.exists(path):
        cur=io.open(path,"r",encoding="utf-8").read()
        if marker in cur:
            print("  [OK   ] %s : deja present (idempotent)"%path); return True
        print("  [ABORT] %s : existe deja SANS le marqueur -> NON ecrase"%path); return False
    content=dec(content_b64)
    try: ast.parse(content)
    except SyntaxError as e:
        print("  [ABORT] %s : contenu invalide (%s)"%(path,e)); return False
    os.makedirs(os.path.dirname(path), exist_ok=True)
    io.open(path,"w",encoding="utf-8").write(content)
    print("  [CREATE] %s : cree"%path); return True

def apply_edits(path, edits):
    if not os.path.exists(path):
        print("  [ABORT] %s introuvable"%path); return False
    src=io.open(path,"r",encoding="utf-8").read(); changed=False
    for old_b,new_b,marker in edits:
        if marker in src: continue
        old=dec(old_b)
        if old not in src:
            print("  [ABORT] %s : ancre absente (%s) -> NON ecrit"%(path,marker)); return False
        src=src.replace(old,dec(new_b),1); changed=True
    if not changed:
        print("  [OK   ] %s : deja applique (idempotent)"%path); return True
    try: ast.parse(src)
    except SyntaxError as e:
        print("  [ABORT] %s : syntaxe invalide -> NON ecrit (%s)"%(path,e)); return False
    io.open(path,"w",encoding="utf-8").write(src)
    print("  [PATCH] %s : modifie"%path); return True

def main():
    ok=True
    ok&=write_new("app/security/entitlement.py", ENT_B64, "def verify_entitlement")
    ok&=apply_edits("app/schemas.py", [SCH])
    ok&=apply_edits("app/api/routes.py", RT)
    if not ok: sys.exit(1)
    print("\n>>> Termine. Reconstruisez l'image puis redemarrez le conteneur.")

if __name__=="__main__":
    main()
